mod hopscotch;

use hopscotch::HopscotchMap;

/// Reproduce C++ `std::stoi` semantics:
/// - skips leading whitespace (C locale),
/// - optional '+'/'-' sign,
/// - parses the leading run of decimal digits, ignoring trailing junk,
/// - aborts (uncaught std::invalid_argument / std::out_of_range in C++)
///   when there are no digits or the value is out of `int` range.
fn stoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
        i += 1;
    }
    let mut neg = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        neg = bytes[i] == b'-';
        i += 1;
    }
    let start = i;
    let mut val: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        val = val * 10 + (bytes[i] - b'0') as i64;
        if val > 10_000_000_000 {
            // Far beyond i32 range; clamp to avoid i64 overflow on huge
            // digit runs. Still out_of_range either way.
            val = 10_000_000_000;
        }
        i += 1;
    }
    if i == start {
        // std::invalid_argument, uncaught -> abort
        std::process::abort();
    }
    if neg {
        val = -val;
    }
    if val < i32::MIN as i64 || val > i32::MAX as i64 {
        // std::out_of_range, uncaught -> abort
        std::process::abort();
    }
    val as i32
}

/// Format like C++ `std::cout << float` (default `%g`, 6 significant digits,
/// trailing zeros stripped). Input is the f32 load factor widened to f64.
fn format_g(f: f64) -> String {
    const P: i32 = 6; // significant digits
    if f == 0.0 {
        return "0".to_string();
    }
    // {:.5e} yields a correctly rounded (round-half-to-even) 6-sig-digit
    // mantissa plus the decimal exponent of the rounded value.
    let s = format!("{:.*e}", (P - 1) as usize, f);
    let epos = s.find('e').unwrap();
    let exp: i32 = s[epos + 1..].parse().unwrap();
    if exp < -4 || exp >= P {
        // %g scientific branch (not reached by this program's values,
        // which all lie in (0, 1], but implemented for completeness).
        let mantissa = s[..epos].trim_end_matches('0').trim_end_matches('.');
        format!("{}e{}{:02}", mantissa, if exp < 0 { '-' } else { '+' }, exp.abs())
    } else {
        // Fixed notation with P-1-exp digits after the point, then strip
        // trailing zeros and a possible trailing '.'.
        let prec = (P - 1 - exp) as usize;
        let fixed = format!("{:.*}", prec, f);
        fixed.trim_end_matches('0').trim_end_matches('.').to_string()
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut count: i32 = 11;
    if args.len() > 1 && args[1] == "--a" {
        count = stoi(&args[2]);
    }

    let mut map = HopscotchMap::new();
    let mut i: i32 = 0;
    while i < count {
        map.insert(i, i * 9);
        i += 1;
    }

    let g1 = format_g(map.load_factor() as f64);
    map.set_max_load_factor(0.5);
    map.rehash(0);
    let g2 = format_g(map.load_factor() as f64);

    println!("{} {}", g1, g2);
}

